const cx = (...classes: Array<string | false | undefined>) => classes.filter(Boolean).join(' ');

function Pill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'teal' | 'amber' | 'red' | 'green' }) {
  const tones = {
    neutral: 'bg-[#e9e6de] text-[#566267]',
    teal: 'bg-[#d7eeee] text-[#14636a]',
    amber: 'bg-[#fff0c9] text-[#7b5600]',
    red: 'bg-[#f9dcda] text-[#9b312c]',
    green: 'bg-[#dcefe2] text-[#27613d]',
  };
  return <span className={cx('inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-semibold tracking-wide', tones[tone])}>{children}</span>;
}

function Button({ children, onClick, variant = 'primary', disabled = false, icon, testId, className = '', type = 'button' }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; disabled?: boolean; icon?: ReactNode; testId?: string; className?: string; type?: 'button' | 'submit' }) {
  const styles = {
    primary: 'bg-[#146b73] text-[#f8f5ed] shadow-[0_5px_14px_rgba(20,107,115,.16)] hover:bg-[#0d5961]',
    secondary: 'bg-[#f4f0e6] text-[#20323b] border border-[#d7d1c5] hover:bg-[#ebe5d8]',
    ghost: 'text-[#54636a] hover:bg-[#ebe8df] hover:text-[#20323b]',
    danger: 'bg-[#a83d37] text-white hover:bg-[#91322e]',
  };
  return <button data-testid={testId} type={type} onClick={onClick} disabled={disabled} className={cx('inline-flex min-h-10 items-center justify-center gap-2 rounded-md px-4 text-sm font-semibold transition-all duration-200 active:translate-y-px disabled:cursor-not-allowed disabled:opacity-45', styles[variant], className)}>{icon}{children}</button>;
}

function StatusIcon({ status }: { status: 'complete' | 'active' | 'pending' | 'warning' | 'blocked' }) {
  if (status === 'complete') return <CheckCircle2 className="h-4 w-4 text-[#2b7a4b]" />;
  if (status === 'warning') return <AlertTriangle className="h-4 w-4 text-[#b67200]" />;
  if (status === 'blocked') return <XCircle className="h-4 w-4 text-[#a83d37]" />;
  if (status === 'active') return <span className="relative flex h-4 w-4 items-center justify-center"><span className="absolute h-3 w-3 animate-dot rounded-full bg-[#e4a62b]/30" /><span className="h-1.5 w-1.5 rounded-full bg-[#d28c12]" /></span>;
  return <CircleDashed className="h-4 w-4 text-[#97a2a5]" />;
}

