function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 border-b border-[#d9d5ca] pb-6 md:flex-row md:items-end"><div><div className="mb-2 font-mono-ui text-[10px] uppercase tracking-[.19em] text-[#a16d08]">{eyebrow}</div><h1 className="font-display text-3xl font-semibold tracking-[-.04em] text-[#20323b] md:text-[38px]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#66747a]">{description}</p>}</div>{action}</div>;
}

function Metric({ label, value, note, icon: Icon, tone = 'teal' }: { label: string; value: string; note: string; icon: typeof Activity; tone?: 'teal' | 'amber' | 'green' }) {
  return <div className="rounded-md border border-[#d9d5ca] bg-[#f8f5ed] p-4 shadow-[0_1px_2px_rgba(32,50,59,.03)]"><div className="mb-4 flex items-start justify-between"><span className="font-mono-ui text-[10px] uppercase tracking-[.12em] text-[#718087]">{label}</span><span className={cx('rounded-md p-2', tone === 'teal' ? 'bg-[#d7eeee] text-[#146b73]' : tone === 'amber' ? 'bg-[#fff0c9] text-[#a16d08]' : 'bg-[#dcefe2] text-[#2b7a4b]')}><Icon className="h-4 w-4" /></span></div><div className="font-display text-3xl font-semibold tracking-[-.04em] text-[#20323b]">{value}</div><div className="mt-1 text-xs text-[#718087]">{note}</div></div>;
}

